with contextlib.redirect_stdout(_buffer):
    exec(compile('"""Independent literal-input economic reconstruction. Does not import production model."""\nimport json, pathlib\n\ndef reconstruct(roic):\n    weights=[8.084164,7.40496,3.185874,4.253918,4.001118,.630690]\n    sales=[(2785832825.02+2176453423.64-1933406991.48)/1e8*v/sum(weights) for v in weights]\n    prior=sum(sales);pc=22.;dom=5.5926431881;foreign=1.5;dr=fr=ds=fs=0.;pr=12.8392613104;ps=2.7616994379;lossret=-.1;value=0.;terminal=0.;audit=[]\n    for year in range(1,201):\n        fading=min(1.,(year-1)/9)\n        sales=[v*(1+g*(1-fading)+.025*fading) for v,g in zip(sales,[.16,.055,.05,.07,.025,.03])]\n        total=sum(sales);profit=sum(v*m for v,m in zip(sales,[.355,.295,.29,.25,.19,.20]))-.01\n        da=total*.05;working=(total-prior)*.32\n        spend=da+[5.7,4.4,2.,.7,.5][year-1] if year<6 else max(da*.7,da+profit*max(.025,total/prior-1)/roic-working)\n        retained_in_business=spend-da+working\n        p_interest=pc*.0125;di=dom*.0125;fi=foreign*.0125;s_interest=di+fi\n        loss=.06 if year<=5 else .05 if year==6 else 0;lossret-=loss\n        interest=5.455263*(.018 if year==1 else .025 if year==2 else 0)\n        maturity=5.455263*1.15 if year==3 else 0\n        bank=.4703542275 if year==1 else 0\n        oldpay=.8 if year==1 else 0\n        assets=2.7885231992*.8/5 if year in range(8,13) else 0\n        writeoff=2.7885231992*.2 if year==1 else 0\n        pp=profit*.55+p_interest-interest-(5.455263*.15 if year==3 else 0)-writeoff\n        dp=profit*.32+di;fp=profit*.13+fi\n        flow_p=profit*.55+p_interest-retained_in_business*.65-interest-maturity-bank-oldpay+assets-loss\n        df=profit*.32+di-retained_in_business*.35*(.32/.45)\n        ff=profit*.13+fi-retained_in_business*.35*(.13/.45)\n        old=pc+dom+foreign;pc+=flow_p;dom+=df;foreign+=ff\n        dm=total*.045*(.32/.45);fm=total*.045*(.13/.45)\n        fund_d=max(0,dm-dom);fund_f=max(0,fm-foreign);pc-=fund_d+fund_f;dom+=fund_d;foreign+=fund_f\n        dradd=min(.1*max(0,dp+min(0,dr)),max(0,3-ds));dr+=dp-dradd;ds+=dradd\n        fradd=min(.1*max(0,fp+min(0,fr)),max(0,1-fs));fr+=fp-fradd;fs+=fradd\n        dtarget=max(0,df)*.9+(.2*max(0,dom-dm) if year>5 else 0)\n        ftarget=max(0,ff)*.9+(.2*max(0,foreign-fm) if year>5 else 0)\n        ud=max(0,min(dtarget,max(0,dr),max(0,dom-dm)))\n        uf=max(0,min(ftarget,max(0,fr),max(0,foreign-fm)))\n        dr-=ud;fr-=uf;dom-=ud;foreign-=uf\n        remittance=uf*.05;up=ud+uf-remittance;pc+=up;pp+=up-loss\n        sc=dom+foreign;sr=dr+fr\n        padd=min(.1*max(0,pp+min(0,pr)),max(0,5.09140859*.5-ps));pr+=pp-padd;ps+=padd\n        wanted=[.4,.45,.5,.55,.6][year-1]*5.08590859 if year<6 else max(0,flow_p+up)+.2*max(0,pc-total*.065)\n        d=max(0,min(wanted,max(0,pr),max(0,pc-total*.065)));pc-=d;pr-=d\n        error=pc+sc-(old+profit-retained_in_business+p_interest+s_interest-interest-maturity-bank-oldpay+assets-d-loss-remittance)\n        assert abs(error)<1e-7*max(1,pc+sc)\n        per=d/5.08590859;value+=per/1.105**year\n        if year>5:terminal+=per/1.105**(year-5)\n        audit.append([year,total,profit,spend,working,pc,sc,pr,sr,up,per,error]);prior=total\n    tail=per*1.025/(.105-.025);value+=tail/1.105**200;terminal+=tail/1.105**195\n    return {\'value\':value,\'terminal\':terminal,\'annual_economic_rows\':audit}\n\nif __name__==\'__main__\':\n    here=pathlib.Path(__file__).resolve().parent\n    actual=json.loads((here/\'2026-Q3-output.json\').read_text())[\'cases\']\n    out={}\n    for n,r in [(\'core_low\',.18),(\'core_low_roic12\',.12)]:\n        v=reconstruct(r);v[\'value_error\']=v[\'value\']-actual[n][\'value\'];v[\'terminal_error\']=v[\'terminal\']-actual[n][\'terminal_year5\'];assert abs(v[\'value_error\'])<1e-10 and abs(v[\'terminal_error\'])<1e-10\n        for a,b in zip(v[\'annual_economic_rows\'],actual[n][\'rows\']):\n            assert abs(a[10]-b[\'dps\'])<1e-8\n        out[n]=v\n    print(json.dumps(out,ensure_ascii=False,sort_keys=True,indent=2))\n', __file__, "exec"), {"__file__":__file__, "__name__":"__main__"})
