exec(compile("from pathlib import Path\nfrom decimal import Decimal as D\nimport json,pathlib,importlib.util,hashlib,zipfile\nroot=pathlib.Path(__file__).resolve().parent;o=json.loads((root/'2026-Q3-output.json').read_text());weights=list(map(D,['8.084164','7.40496','3.185874','4.253918','4.001118','.630690']));ttm=(D('2785832825.02')+D('2176453423.64')-D('1933406991.48'))/D('1e8');checks=[]\nfor name,growth,margins in [('core_low',['.16','.055','.05','.07','.025','.03'],['.355','.295','.29','.25','.19','.20']),('core_high',['.20','.075','.065','.09','.04','.04'],['.385','.315','.31','.27','.21','.23'])]:\n rev=sum(ttm*w/sum(weights)*(1+D(g)) for w,g in zip(weights,growth));profit=sum(ttm*w/sum(weights)*(1+D(g))*D(m) for w,g,m in zip(weights,growth,margins))-D('.01');wc=(rev-ttm)*D('.32');cap=rev*D('.05')+D('5.7');fcf=profit-D('5.7')-wc\n row=o['cases'][name]['rows'][0]\n for field,val in [('revenue',rev),('common_operating_profit',profit),('delta_working_capital',wc),('capex',cap),('fcf',fcf)]:assert abs(float(val)-row[field])<1e-10;checks.append([name,field,float(val)])\n # independently separate domestic and overseas, legal profits no preexisting reserves\n for label,w,cash in [('domestic',D('.32'),D('5.5926431881')),('overseas',D('.13'),D('1.5'))]:\n  ep=profit*w+cash*D('.0125');assert abs(float(ep)-row[label+'_profit_budget'])<1e-10\nfor name,v in o['cases'].items():\n rows=v['rows'];k=v['parameters']['k'];g=v['parameters']['g'];h=v['horizon'];pv=sum(r['dps']/(1+k)**r['year'] for r in rows)+rows[-1]['dps']*(1+g)/(k-g)/(1+k)**h\n assert abs(pv-v['value'])<1e-10\n for r in rows:\n  assert r['risk_dividend']==0 and r['domestic_cash']>=0 and r['overseas_cash']>=0\n  assert abs(r['subsidiary_upstream']-(r['domestic_upstream']+r['overseas_gross_upstream']-r['overseas_remittance_tax']))<1e-9\n  assert abs(r['cash_conservation_error'])<1e-6\n if v['convert']:assert all(r['coupon']==0 and r['redemption']==0 for r in rows)\n else:assert abs(rows[2]['redemption']-5.455263*1.15)<1e-12 and rows[2]['coupon']==0\n assert abs((rows[-1]['parent_cash']+rows[-1]['subsidiary_cash'])/rows[-1]['revenue']-.11)<1e-8\nsp=importlib.util.spec_from_file_location('prod',root/'2026-Q3.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)\na=m.pay(-5,0,100,4,100,0,100);b=m.pay(a[0],a[1],100,4,a[2]+4,0,100);assert a[3]==0 and abs(b[3]-2.7)<1e-12 and abs(b[4]-.3)<1e-12\nprint(json.dumps({'independent_decimal_firstyear':checks,'all_scenarios_actual_cash_holder_PV_bond_checks':len(o['cases']),'actual_production_lossfirst':[a,b],'max_convergence_spread':max(v['value_spread'] for v in o['tail_convergence'].values())},indent=2))\n", __file__, "exec"), {"__file__":__file__, "__name__":"__main__", "_AUTHOR_JSON":_buffer.getvalue() if _buffer else ""})
